def book_of(text):
    t = text or ''
    best = None
    for k, v in BOOK.items():
        if k in t and not _den('BOOK', k) and (best is None or len(k) > len(best[0])): best = (k, v)
    return best


def book_link(k):
    u = BOOK_URL.get(k)
    if u: return f'<a class="bkl" href="{E(u)}" rel="nofollow noopener" target="_blank">官网预约 ›</a>'
    h = BOOK_HOW.get(k)
    return f'<span class="bkh">{E(h)}预约</span>' if h else ''


