CUR_RID = [None]     # 正在生成哪条线的页面（串线闸要按线判断）
DENY = set()         # {(表名, 键, 线编号)}：这条文案不该出现在这条线里（同名但在别处的景点）


def _den(tab, k):
    return (tab, k, CUR_RID[0]) in DENY


def sight_of(text):
    t = text or ''
    best = None
    for k, v in SIGHT.items():
        if k in t and not _den('SIGHT', k) and (best is None or len(k) > len(best[0])): best = (k, v)     # 最长的键优先：“沈阳故宫”不能拿到“故宫”的介绍
    return best[1] if best else None


TZ = {'japan': 9, 'korea': 9, 'thailand': 7, 'vietnam': 7, 'cambodia': 7, 'laos': 7, 'malaysia': 8, 'singapore': 8, 'indonesia': 8, 'philippines': 8,
      'nepal': 5.75, 'bhutan': 6, 'india': 5.5, 'srilanka': 5.5, 'maldives': 5, 'uzbekistan': 5, 'kazakhstan': 5, 'turkey': 3, 'uae': 4, 'georgia': 4,
      'jordan': 3, 'mongolia': 8}
# “更远”的国家：标准时区 + 夏令时规则名（eu 欧盟 / us 美加 / au 澳洲东南 / nz 新西兰 / eg 埃及；空 = 不实行）。多时区国家按经度分
TZ.update({'france': 1, 'italy': 1, 'spain': 1, 'switzerland': 1, 'czech': 1, 'austria': 1, 'germany': 1, 'netherlands': 1, 'croatia': 1, 'norway': 1, 'belgium': 1,
           'greece': 2, 'finland': 2, 'portugal': 0, 'uk': 0, 'ireland': 0, 'iceland': 0, 'morocco': 1, 'egypt': 2, 'southafrica': 2, 'peru': -5, 'newzealand': 12})
DST = {k: 'eu' for k in ('france', 'italy', 'spain', 'switzerland', 'czech', 'austria', 'germany', 'netherlands', 'croatia', 'norway', 'belgium', 'greece', 'finland', 'portugal', 'uk', 'ireland')}
DST.update({'egypt': 'eg', 'usa': 'us', 'canada': 'us', 'australia': 'au', 'newzealand': 'nz'})


def tz_of(dest, lng):
    """某目的地、某经度的 (标准时区, 夏令时规则名)。"""
    if dest in ('usa', 'canada'):
        z = -8 if lng < -120 else -7 if lng < -102 else -6 if lng < -87 else -5
    elif dest == 'australia':
        z = 10 if lng > 141 else 9.5 if lng > 129 else 8
    elif dest == 'mexico':
        z = -5 if lng > -88.0 else -6     # 金塔纳罗奥（坎昆、图卢姆）东五区；尤卡坦（奇琴伊察）和墨西哥城东六区
    else:
        z = TZ.get(dest, 8)
    rule = DST.get(dest, '')
    if dest == 'usa' and lng < -140: z, rule = -10, ''     # 夏威夷：UTC-10，不实行夏令时
    if dest == 'australia' and lng <= 141: rule = ''     # 只有东南沿海（悉尼、墨尔本）有夏令时
    return z, rule
